    msg.payload = { ok: false, error: "Yêu cầu đăng nhập (thiếu token xác thực trong header Authorization)" };
    msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
    return [null, msg];
}

var sessions = global.get("sessions") || {};
var session = sessions[token];
if (!session && token === "demo_admin_token") { session = { user_id: 1, username: "admin", full_name: "Quản trị viên", role: "admin" }; }
if (!session && token === "demo_user_token") { session = { user_id: 2, username: "user", full_name: "Người dùng", role: "user" }; }
if (!session && token === "demo_viewer_token") { session = { user_id: 3, username: "viewer", full_name: "Người xem", role: "viewer" }; }

if (!session) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: "Token xác thực không hợp lệ hoặc phiên làm việc đã hết hạn. Vui lòng đăng nhập lại." };
    msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
    return [null, msg];
}

if (session.role !== "admin" && session.role !== "user") {
    msg.statusCode = 403;
    msg.payload = { ok: false, error: "Tài khoản " + session.role + " không có quyền truy cập lịch sử điều khiển (chỉ admin và user)" };
    msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
    return [null, msg];
}

var q = msg.req.query || {};
var rawDevice = (q.device || "").trim();
var status = (q.status || "").trim();
var action = (q.action || "").trim().toUpperCase();  // ON | OFF
var time = (q.time || "").trim();                    // vd: 2026-10-09 hoac 2026-10-09 14:30
var page = Math.max(parseInt(q.page) || 1, 1);
var pageSize = Math.min(Math.max(parseInt(q.pageSize || q.limit) || 10, 1), 100);   // ho tro ca pageSize va limit
var offset = (page - 1) * pageSize;

var where = [];
var params = [];
if (rawDevice) {
    var devId = (rawDevice === "led1" || rawDevice === "1") ? 1 : ((rawDevice === "led2" || rawDevice === "2") ? 2 : parseInt(rawDevice));
    if (devId) {
        where.push("a.device_id = ?");
        params.push(devId);
    }
}
if (status) { where.push("a.status = ?"); params.push(status); }
if (action === "ON" || action === "OFF") { where.push("a.action LIKE ?"); params.push("%:" + action); }
if (time) { where.push("DATE_FORMAT(a.time, '%Y-%m-%d %H:%i:%s') LIKE ?"); params.push("%" + time.replace(/[\\%_]/g, "\\$&") + "%"); }
var whereSQL = where.length ? ("WHERE " + where.join(" AND ")) : "";

msg._page = page; msg._pageSize = pageSize; msg._where = whereSQL; msg._params = params;

msg.topic = "SELECT a.action_id, a.device_id, d.device_name, a.user_id, u.full_name AS user_full_name, u.username AS user_username, a.action, a.status, a.time, a.time_response FROM actions a LEFT JOIN devices d ON d.device_id = a.device_id LEFT JOIN users u ON u.user_id = a.user_id " + whereSQL + " ORDER BY a.time DESC, a.action_id DESC LIMIT ? OFFSET ?";
msg.payload = params.concat([pageSize, offset]);
return [msg, null];

msg._rows = msg.payload;
msg.topic = "SELECT COUNT(*) AS total FROM actions a " + msg._where;
msg.payload = msg._params;
return msg;

var rows = msg._rows.map(function (r) {
    var ms = null;
    if (r.time_response) {
        ms = new Date(r.time_response).getTime() - new Date(r.time).getTime();
    } else if (r.status === "timeout") {
        ms = 5000;
    }
    r.response_ms = ms;
    r.operator = r.user_id ? (r.user_full_name || r.user_username || "Người dùng") : "MQTT";
    return r;
});

msg.payload = { rows: rows, total: msg.payload[0].total, page: msg._page, pageSize: msg._pageSize };
msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
return msg;

var body = msg.payload || {};
var device = body.device;
var action = (body.action || "").toUpperCase();

var authHeader = (msg.req && msg.req.headers && (msg.req.headers["authorization"] || msg.req.headers["Authorization"])) || "";
var token = "";
if (authHeader.indexOf("Bearer ") === 0) {
    token = authHeader.substring(7).trim();
} else if (body.token) {
    token = body.token;
}

if (!token) {
