    msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
    return [null, msg];
}

if ((device !== "led1" && device !== "led2") || (action !== "ON" && action !== "OFF")) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: "device phải là led1/led2, action phải là ON/OFF" };
    msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
    return [null, msg];
}

var key = "ui_cmd_" + device;
var list = (global.get(key) || []).filter(function (item) {
    var t = (typeof item === "object") ? item.time : item;
    return Date.now() - t < 5000;
});
list.push({ time: Date.now(), user_id: session.user_id });
global.set(key, list);

msg.topic = "device/control/" + device;
msg.payload = action;
return [msg, null];

msg.payload = { ok: true, device: msg.topic.split("/").pop(), action: msg.payload };
