msg.topic = "SELECT user_id, username, full_name, email FROM users ORDER BY user_id LIMIT 1";
msg.payload = [];
return [msg, null];

var r = (msg.payload && msg.payload[0]) || {};
msg.payload = { username: r.username || "", full_name: r.full_name || "", email: r.email || "" };
msg.headers = { "Access-Control-Allow-Origin": "*" };
return msg;

var body = msg.payload || {};
var username = (body.username || "").trim();
