if (!session && token === "demo_user_token") { session = { user_id: 2, username: "user", full_name: "Người dùng", role: "user" }; }
if (!session && token === "demo_viewer_token") { session = { user_id: 3, username: "viewer", full_name: "Người xem", role: "viewer" }; }

if (!session) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: "Token xác thực không hợp lệ hoặc phiên làm việc đã hết hạn. Vui lòng đăng nhập lại." };
    msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
    return [null, msg];
}

if (session.role !== "admin" && session.role !== "user") {
    msg.statusCode = 403;
    msg.payload = { ok: false, error: "Tài khoản " + session.role + " không có quyền truy cập danh sách loại cảm biến" };
    msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
    return [null, msg];
}

msg.topic = "SELECT sensor_id, sensor_code, sensor_name, sensor_type, unit, alert_threshold FROM sensors ORDER BY sensor_id ASC;";
return [msg, null];

msg.statusCode = 200;
msg.payload = {
    ok: true,
    sensors: msg.payload || []
};
msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers": "Content-Type, Authorization"
};
return msg;
